theorem documented_sqrtTwo_mem_every_resolution_space
    (Resolved : (ℕ → ℝ) → DocumentedRemainder → Prop) :
    (fun _ : ℕ => Real.sqrt 2) ∈ {a : ℕ → ℝ | ∀ U, Resolved a U}

proof:
:= by
  obtain ⟨N, hN⟩ : ∃ N : ℕ, ∀ n ≥ N, n ∈ S → (p.eval (n : ℚ) : ℚ) = (p.eval (N : ℚ) : ℚ) := by
    obtain ⟨ N, hN ⟩ := Filter.eventually_atTop.mp h;

    obtain ⟨n, hn₁, hn₂⟩ : ∃ n ≥ N, n ∈ S := by
      have := mem_infinite ( U := U ) hS;
      exact Exists.elim ( this.exists_gt N ) fun n hn => ⟨ n, hn.2.le, hn.1 ⟩;
    exact ⟨ n, fun m hm₁ hm₂ => by have := hN m ( by linarith ) hm₂; have := hN n ( by linarith ) hn₂; aesop ⟩;
  have h_inf : Set.Infinite {n : ℕ | n ≥ N ∧ n ∈ S} := by
    exact Set.infinite_of_forall_exists_gt fun n => by rcases QPCF.Beta.mem_infinite U ( Filter.mem_of_superset hS ( Set.Subset.refl _ ) ) |> Set.Infinite.exists_gt <| n + N with ⟨ m, hm₁, hm₂ ⟩ ; exact ⟨ m, ⟨ by linarith, hm₁ ⟩, by linarith ⟩ ;
  have h_const : p = Polynomial.C (p.eval (N : ℚ)) := by
    have h_const : Set.Infinite {n : ℚ | p.eval n = p.eval (N : ℚ)} := by
      exact Set.infinite_of_forall_exists_gt fun x => by rcases h_inf.exists_gt ⌈x⌉₊ with ⟨ n, hn₁, hn₂ ⟩ ; exact ⟨ n, by simpa using hN n hn₁.1 hn₁.2, Nat.lt_of_ceil_lt hn₂ ⟩ ;
    exact Classical.not_not.1 fun h => h_const <| Set.Finite.subset ( p - Polynomial.C ( Polynomial.eval ( N : ℚ ) p ) |> Polynomial.roots |> Multiset.toFinset |> Finset.finite_toSet ) fun x hx => by simp_all +decide [ sub_eq_iff_eq_add ] ;
  rw [ h_const, Polynomial.natDegree_C ]

:= by
  revert h;
  rintro ⟨ P, Q, hQ, h ⟩ hc_irr
  obtain ⟨ S, hS, h_const ⟩ : ∃ S : Set ℕ, S ∈ U.1 ∧ ∃ C : ℝ, ∀ᶠ n in atTop, n ∈ S → |c - (((P.eval (n : ℚ) : ℚ) : ℝ) / ((Q.eval (n : ℚ) : ℚ) : ℝ))| ≤ C * (n : ℝ) ^ (-1 : ℤ) := by
    obtain ⟨ S, hS₁, hS₂ ⟩ := h 1; exact ⟨ S, hS₁, 1, by filter_upwards [ hS₂ ] with n hn hn' using by simpa using hn hn' |>.2 ⟩ ;

  have h_rat_lim : Filter.Tendsto (fun n : ℕ => ((P.eval (n : ℚ) : ℚ) : ℝ) / ((Q.eval (n : ℚ) : ℚ) : ℝ)) (Filter.atTop ⊓ Filter.principal S) (nhds c) := by
    obtain ⟨ C, hC ⟩ := h_const;
    rw [ Metric.tendsto_nhds ];
    intro ε hε; rw [ Filter.eventually_inf_principal ] ; filter_upwards [ hC, Filter.eventually_gt_atTop ⌈ε⁻¹ * C⌉₊ ] with n hn hn' ; simp_all +decide [ dist_eq_norm' ] ;
    intro hnS; refine lt_of_le_of_lt ( hn hnS ) ?_; rw [ mul_inv_lt_iff₀ ] <;> nlinarith [ Nat.lt_of_ceil_lt hn', inv_pos.mpr hε, mul_inv_cancel₀ hε.ne', show ( n : ℝ ) ≥ ⌈ε⁻¹ * C⌉₊ + 1 by exact_mod_cast hn' ] ;

  by_cases h_deg : P.degree < Q.degree;
  · have h_lim_zero : Filter.Tendsto (fun n : ℕ => ((P.eval (n : ℚ) : ℚ) : ℝ) / ((Q.eval (n : ℚ) : ℚ) : ℝ)) Filter.atTop (nhds 0) := by
      have := Polynomial.div_tendsto_atTop_zero_of_degree_lt ( Polynomial.map ( algebraMap ℚ ℝ ) P ) ( Polynomial.map ( algebraMap ℚ ℝ ) Q ) ?_ <;> simp_all +decide [ Polynomial.degree_map ];
      convert this.comp tendsto_natCast_atTop_atTop using 2 ; norm_num [ Polynomial.aeval_def ];
    convert absurd ( tendsto_nhds_unique h_rat_lim <| h_lim_zero.mono_left inf_le_left ) ( by aesop ) using 1;
    refine' Filter.neBot_iff.mpr _;
    simp +decide [ Filter.inf_principal_eq_bot ];
    exact fun n => by rcases Set.Infinite.exists_gt ( QPCF.Beta.mem_infinite U hS ) n with ⟨ m, hm₁, hm₂ ⟩ ; exact ⟨ m, hm₂.le, hm₁ ⟩ ;
  · by_cases h_deg : P.degree > Q.degree;
    · have h_abs_diverge : Filter.Tendsto (fun n : ℕ => |((P.eval (n : ℚ) : ℚ) : ℝ) / ((Q.eval (n : ℚ) : ℚ) : ℝ)|) (Filter.atTop ⊓ Filter.principal S) Filter.atTop := by
        have h_abs_diverge : Filter.Tendsto (fun n : ℕ => |((P.eval (n : ℚ) : ℚ) : ℝ)| / |((Q.eval (n : ℚ) : ℚ) : ℝ)|) Filter.atTop Filter.atTop := by
          have h_abs_diverge : Filter.Tendsto (fun x : ℚ => |((P.eval x : ℚ) : ℝ)| / |((Q.eval x : ℚ) : ℝ)|) Filter.atTop Filter.atTop := by
            have := Polynomial.abs_div_tendsto_atTop_atTop_of_degree_gt ( Polynomial.map ( algebraMap ℚ ℝ ) P ) ( Polynomial.map ( algebraMap ℚ ℝ ) Q ) ; simp_all +decide [ Polynomial.degree_map ] ;
            convert this.comp ( show Filter.Tendsto ( fun x : ℚ => ( x : ℝ ) ) Filter.atTop Filter.atTop from Filter.tendsto_atTop_atTop.mpr _ ) using 2 ; norm_num [ abs_div ];
            · simp +decide [ Polynomial.aeval_def, Polynomial.eval₂_eq_sum_range ];
              simp +decide [ Polynomial.eval_eq_sum_range ];
            · exact fun x => ⟨ ⌈x⌉, fun n hn => le_trans ( Int.le_ceil _ ) ( mod_cast hn ) ⟩
          exact h_abs_diverge.comp tendsto_natCast_atTop_atTop;
        simpa only [ abs_div ] using h_abs_diverge.mono_left inf_le_left;
      convert not_tendsto_atTop_of_tendsto_nhds ( h_rat_lim.abs ) h_abs_diverge using 1;
      refine' Filter.neBot_iff.mpr _;
      simp +decide [ Filter.inf_principal_eq_bot ];
      exact fun n => by rcases Set.Infinite.exists_gt ( QPCF.Beta.mem_infinite U hS ) n with ⟨ m, hm₁, hm₂ ⟩ ; exact ⟨ m, hm₂.le, hm₁ ⟩ ;
    · 
      have h_leading_coeff : Filter.Tendsto (fun n : ℕ => ((P.eval (n : ℚ) : ℚ) : ℝ) / ((Q.eval (n : ℚ) : ℚ) : ℝ)) Filter.atTop (nhds ((P.leadingCoeff : ℝ) / (Q.leadingCoeff : ℝ))) := by
        have := Polynomial.div_tendsto_atTop_leadingCoeff_div_of_degree_eq ( P.map ( algebraMap ℚ ℝ ) ) ( Q.map ( algebraMap ℚ ℝ ) ) ; simp_all +decide [ Polynomial.degree_map ] ;
        convert this ( le_antisymm h_deg ‹_› ) |> Filter.Tendsto.comp <| tendsto_natCast_atTop_atTop using 2 ; norm_num [ Polynomial.aeval_def ];
      have h_leading_coeff_eq : c = (P.leadingCoeff : ℝ) / (Q.leadingCoeff : ℝ) := by
        convert tendsto_nhds_unique h_rat_lim ( h_leading_coeff.mono_left inf_le_left ) using 1;
        refine' Filter.neBot_iff.mpr _;
        simp +decide [ Filter.inf_principal_eq_bot ];
        exact fun n => by have := mem_infinite U hS; exact this.exists_gt n |> fun ⟨ m, hm₁, hm₂ ⟩ => ⟨ m, hm₂.le, hm₁ ⟩ ;
      exact hc_irr ⟨ P.leadingCoeff / Q.leadingCoeff, by push_cast; linarith ⟩

:= by
  intro U
  by_cases hU : {n : ℕ | ∃ q : ℕ, n = q^2} ∈ (U : Ultrafilter ℕ);
  · refine' Or.inl ⟨ 2, Polynomial.X, _, _ ⟩ <;> norm_num;
    intro k; use { n : ℕ | ∃ q : ℕ, n = q ^ 2 } ; simp_all +decide [ squareSeparator ] ;
    exact ⟨ 1, by intros; nlinarith ⟩;
  · refine' Or.inl ⟨ 1, Polynomial.X, _, _ ⟩ <;> norm_num;
    intro k;
    refine' ⟨ { n : ℕ | ¬∃ q : ℕ, n = q ^ 2 }, _, 1, _ ⟩ <;> norm_num;
    · convert U.1.compl_mem_iff_notMem.mpr hU using 1;
      aesop;
    · intro b hb hb'; unfold squareSeparator; aesop;

:= by
  refine' ⟨ _, ⟨ _, rfl ⟩, _ ⟩;
  · unfold ThreadClass;
    unfold squareSample; simp +decide [ ZHat.proj, ZHat.ofNat ] ;
  · unfold squareSample; norm_num [ Nat.add_mod, Nat.mul_mod, Nat.pow_mod ] ;

:= by
  refine' ⟨ _, fun ⟨ q, hq ⟩ => _ ⟩;
  · unfold ThreadClass;
    unfold nonsquareSample squareSample; simp +decide [ ZHat.proj, ZHat.ofNat ] ;
  · 
    have h_nonsquareSample : nonsquareSample M k = (1 + 2 * (k + 1) * M.factorial) ^ 2 + M.factorial := by
      rfl;

    have h_q_gt : q > 1 + 2 * (k + 1) * M.factorial := by
      nlinarith [ Nat.factorial_pos M ];
    nlinarith only [ hq, h_nonsquareSample, h_q_gt, Nat.self_le_factorial M, show k * M.factorial ≥ 0 by positivity ]

:= by
  refine' Filter.tendsto_atTop_atTop.2 fun x => _;
  exact ⟨ x, fun a ha => by unfold squareSample; nlinarith [ Nat.factorial_pos M, mul_pos ( Nat.succ_pos a ) ( Nat.factorial_pos M ) ] ⟩

:= by
  unfold realPQ;
  rw [ show realGaussIter 1 ( 2 / ( n : ℝ ) ) = ( ( 2 / ( n : ℝ ) ) ⁻¹ ) from ?_ ];
  · rcases Nat.even_or_odd' n with ⟨ k, rfl | rfl ⟩ <;> norm_num at *;
    ring_nf; norm_num;
  · convert realGaussIter_succ_fract 0 ( 2 / n ) using 1 ; ring_nf;
    rw [ show realGaussIter 0 ( ( n : ℝ ) ⁻¹ * 2 ) = ( n : ℝ ) ⁻¹ * 2 by rfl ] ; norm_num [ show ⌊ ( n : ℝ ) ⁻¹ * 2⌋ = 0 by exact Int.floor_eq_zero_iff.mpr ⟨ by positivity, by nlinarith [ ( by norm_cast : ( 3 :ℝ ) ≤ n ), mul_inv_cancel₀ ( by positivity : ( n :ℝ ) ≠ 0 ) ] ⟩, Int.fract ] ; ring;

:= by
  have h_decay_square : ∀ᶠ n : ℕ in atTop, n ∈ ThreadClass (ZHat.ofNat 1) M → |squareSeparator n - ((P.eval (n : ℚ) : ℚ) / ((Q.eval (n : ℚ) : ℚ) : ℝ))| ≤ (n : ℝ) ^ (-2 : ℤ) := by
    exact hflat.mono fun n hn hn' => hn hn' |>.2;
  have := @QPCF.expansion_order_of_eval_decay;
  constructor;
  · contrapose! this;
    refine' ⟨ P * Polynomial.X - 2 * Q, Q * Polynomial.X, _, 2, 1, _ ⟩ <;> norm_num;
    · exact hQ;
    · refine' ⟨ _, _, _, this ⟩;
      exact { n : ℕ | n ∈ ThreadClass ( ZHat.ofNat 1 ) M ∧ squareSeparator n = 2 / ( n : ℝ ) };
      · refine' Filter.frequently_atTop.mpr _;
        intro a; use ( 1 + 2 * ( a + 1 ) * M.factorial ) ^ 2; simp +decide [ ThreadClass, ZHat.proj, ZHat.ofNat ] ;
        exact ⟨ by nlinarith [ Nat.factorial_pos M, mul_pos ( Nat.succ_pos a ) ( Nat.factorial_pos M ) ], by unfold squareSeparator; norm_num [ Nat.pow_mod, Nat.mul_mod, Nat.add_mod, Nat.factorial_pos ] ⟩;
      · obtain ⟨ N, hN ⟩ := Filter.eventually_atTop.mp h_decay_square;
        refine' ⟨ N + 1, fun n hn hn' => _ ⟩ ; specialize hN n ( by linarith ) hn'.1 ; simp_all +decide [ abs_le, sub_div ];
        by_cases h : Q.eval ( n : ℚ ) = 0 <;> simp_all +decide [ div_eq_mul_inv, mul_assoc, mul_comm, mul_left_comm ];
        · positivity;
        · by_cases hn : n = 0 <;> simp_all +decide [ sq, mul_assoc ];
          constructor <;> linarith;
  · specialize this ( P * Polynomial.X - Q ) ( Q * Polynomial.X );
    contrapose! this;
    refine' ⟨ _, 2, 1, { n : ℕ | n ∈ ThreadClass ( ZHat.ofNat 1 ) M ∧ ¬∃ q : ℕ, n = q ^ 2 }, _, _, this ⟩ <;> norm_num;
    · aesop;
    · refine' Filter.frequently_atTop.2 fun n => _;
      refine' ⟨ nonsquareSample M n, _, _, _ ⟩;
      · unfold nonsquareSample squareSample; nlinarith [ Nat.factorial_pos M, mul_pos ( Nat.succ_pos n ) ( Nat.factorial_pos M ) ] ;
      · exact nonsquareSample_properties M n |>.1;
      · exact fun x hx => nonsquareSample_properties M n |>.2 ⟨ x, hx ⟩;
    · obtain ⟨ N, hN ⟩ := Filter.eventually_atTop.mp hflat; use N; intros n hn hn' hn''; specialize hN n hn hn'; simp_all +decide [ squareSeparator ] ;
      grind

:= by
  by_cases hP : P * Polynomial.X - 2 * Q = 0 <;> by_cases hP' : P * Polynomial.X - Q = 0 <;> simp_all +decide [ Polynomial.natDegree_add_eq_right_of_natDegree_lt ];
  · simp_all +decide [ sub_eq_iff_eq_add ];
  · grind;
  · rw [ show P * Polynomial.X - 2 * Q = -Q by linear_combination' hP' ] ; norm_num [ hQ ];
  · contrapose! hP';
    have h_deg : Polynomial.natDegree (P * Polynomial.X - 2 * Q - (P * Polynomial.X - Q)) ≤ max (Polynomial.natDegree (P * Polynomial.X - 2 * Q)) (Polynomial.natDegree (P * Polynomial.X - Q)) := by
      exact le_trans ( Polynomial.natDegree_sub_le _ _ ) ( max_le_max ( le_rfl ) ( le_rfl ) );
    simp_all +decide [ two_mul, sub_sub ];
    cases h_deg <;> linarith

:= by
  intro h
  obtain ⟨P, Q, hQ, hflat⟩ := h;
  obtain ⟨ M, hM ⟩ := hflat 2;
  exact incompatible_square_sample_decay P Q hQ ( armB_square_sample_decay P Q hQ M hM )

:= by
  intro h
  obtain ⟨S, hS, p, hp⟩ := h;

  have h_poly_eq : ∀ᶠ k in Filter.atTop, (hS 1).eval (squareSample S k : ℚ) = (squareSample S k - 1) / 2 ∧ (hS 1).eval (nonsquareSample S k : ℚ) = nonsquareSample S k := by
    have h_poly_eq : ∀ᶠ k in Filter.atTop, realPQ 1 (squareSeparator (squareSample S k)) = (squareSample S k - 1) / 2 ∧ realPQ 1 (squareSeparator (nonsquareSample S k)) = nonsquareSample S k := by
      refine' Filter.eventually_atTop.mpr ⟨ 2, fun k hk => ⟨ _, _ ⟩ ⟩ <;> norm_num [ squareSeparator ] at *;
      · rw [ if_pos ⟨ 1 + 2 * ( k + 1 ) * S.factorial, rfl ⟩ ];
        convert realPQ_one_two_div_odd_nat _ _ using 1;
        · unfold squareSample; nlinarith [ Nat.factorial_pos S, mul_pos ( Nat.succ_pos k ) ( Nat.factorial_pos S ) ] ;
        · exact squareSample_properties S k |>.2.2;
      · rw [ if_neg ];
        · convert realPQ_one_one_div_nat _ using 1;
          · norm_num;
          · exact le_add_of_le_of_nonneg ( Nat.le_trans ( by nlinarith ) ( Nat.pow_le_pow_left ( show 1 + 2 * ( k + 1 ) * S.factorial ≥ 2 by nlinarith [ Nat.factorial_pos S ] ) 2 ) ) ( Nat.zero_le _ );
        · exact nonsquareSample_properties S k |>.2;
    have h_poly_eq : ∀ᶠ k in Filter.atTop, realPQ 1 (squareSeparator (squareSample S k)) = (hS 1).eval (squareSample S k : ℚ) ∧ realPQ 1 (squareSeparator (nonsquareSample S k)) = (hS 1).eval (nonsquareSample S k : ℚ) := by
      have := p 1;
      rw [ Filter.eventually_atTop ] at *;
      obtain ⟨ a, ha ⟩ := this; use a; intro b hb; exact ⟨ ha _ ( by
        unfold squareSample; nlinarith [ Nat.factorial_pos S, mul_pos ( Nat.succ_pos b ) ( Nat.factorial_pos S ) ] ; ) ( by
        exact squareSample_properties S b |>.1 ), ha _ ( by
        exact le_trans hb ( by unfold nonsquareSample squareSample; nlinarith [ Nat.factorial_pos S, mul_pos ( Nat.succ_pos b ) ( Nat.factorial_pos S ) ] ) ) ( by
        exact nonsquareSample_properties S b |>.1 ) ⟩ ;
    filter_upwards [ ‹∀ᶠ k in atTop, realPQ 1 ( squareSeparator ( squareSample S k ) ) = ( ↑ ( squareSample S k ) - 1 ) / 2 ∧ realPQ 1 ( squareSeparator ( nonsquareSample S k ) ) = ↑ ( nonsquareSample S k ) ›, h_poly_eq ] with k hk₁ hk₂ using by norm_num [ ← @Rat.cast_inj ℝ ] at *; aesop;

  have h_poly_agree : Set.Infinite {n : ℚ | (hS 1).eval n = (n - 1) / 2} ∧ Set.Infinite {n : ℚ | (hS 1).eval n = n} := by
    constructor <;> refine Set.infinite_of_forall_exists_gt ?_;
    · intro a; rcases Filter.eventually_atTop.mp h_poly_eq with ⟨ k, hk ⟩ ; use squareSample S ( k + ⌈a⌉₊ + 1 ) ; norm_num at *;
      exact ⟨ hk _ ( by linarith ) |>.1, by unfold squareSample; norm_num; nlinarith [ Nat.le_ceil a, show ( S.factorial : ℚ ) ≥ 1 from mod_cast Nat.factorial_pos S, show ( k + ⌈a⌉₊ + 1 : ℚ ) * S.factorial ≥ 1 from mod_cast Nat.mul_pos ( Nat.succ_pos _ ) ( Nat.factorial_pos S ) ] ⟩;
    · intro a; rcases Filter.eventually_atTop.mp h_poly_eq with ⟨ k, hk ⟩ ; use nonsquareSample S ( k + ⌊a⌋₊ + 1 ) ; simp_all +decide [ nonsquareSample ] ;
      exact ⟨ hk _ ( by linarith ) |>.2, by exact lt_add_of_lt_of_nonneg ( by exact lt_of_lt_of_le ( Nat.lt_floor_add_one a ) ( mod_cast by unfold squareSample; nlinarith [ Nat.factorial_pos S, mul_pos ( Nat.succ_pos ( k + ⌊a⌋₊ ) ) ( Nat.factorial_pos S ) ] ) ) ( Nat.cast_nonneg _ ) ⟩;

  have h_poly_distinct : (hS 1) = Polynomial.C (1 / 2) * (Polynomial.X - 1) ∧ (hS 1) = Polynomial.X := by
    have h_poly_distinct : ∀ p q : Polynomial ℚ, Set.Infinite {n : ℚ | p.eval n = q.eval n} → p = q := by
      exact fun p q h => Classical.not_not.1 fun hne => h <| Set.Finite.subset ( p - q |> Polynomial.roots |> Multiset.toFinset |> Finset.finite_toSet ) fun x hx => by simp_all +decide [ sub_eq_iff_eq_add ] ;
    exact ⟨ h_poly_distinct _ _ <| h_poly_agree.1.mono fun x hx => by norm_num [ hx.out ] ; ring, h_poly_distinct _ _ <| h_poly_agree.2.mono fun x hx => by norm_num [ hx.out ] ⟩;
  exact absurd ( congr_arg ( Polynomial.eval 0 ) h_poly_distinct.2 ) ( by norm_num [ h_poly_distinct.1 ] )

:= by
  unfold QPCF.Beta.valuationBlock QPCF.Beta.avoidingValuationUltrafilter;
  simp +decide [ Set.preimage ];
  rw [ show { x | 1 ≤ powTwo x ∧ padicValNat 2 ( powTwo x ) = i } = { i } from ?_ ];
  · exact Set.Finite.notMem_hyperfilter ( Set.finite_singleton i );
  · ext x; simp [powTwo];
    exact fun h => Nat.one_le_pow _ _ ( by decide )

