lemma frequently_powTwo_mem_of_mem_avoiding {S : Set ℕ}
    (hS : S ∈ (avoidingValuationUltrafilter.1 : Ultrafilter ℕ)) :
    ∃ᶠ i : ℕ in atTop, powTwo i ∈ S

proof:
:= by
  contrapose! hS; simp_all +decide [ Filter.frequently_atTop ] ;
  obtain ⟨ a, ha ⟩ := hS; exact fun h ↦ Set.Finite.notMem_hyperfilter ( Set.finite_iff_bddAbove.2 ⟨ a, fun x hx ↦ not_lt.1 fun contra ↦ ha x contra.le hx ⟩ ) h;

:= by

  apply funext
  intro j
  apply QPCF.part3_polynomial_pinning;
  convert Set.Infinite.diff ( QPCF.Beta.mem_infinite U ( Filter.inter_mem hS hS' ) ) ( Set.finite_le_nat ( Classical.choose ( Filter.eventually_atTop.mp ( hp j |> Filter.Eventually.and <| hp' j ) ) ) ) using 1;
  intro n hn; have := Classical.choose_spec ( Filter.eventually_atTop.mp ( hp j |> Filter.Eventually.and <| hp' j ) ) n ( le_of_not_ge hn.2 ) ; aesop;

:= by
  intro h
  have h_evenSet : evenSetᶜ ∈ U := by
    have := U.mem_or_compl_mem evenSet;
    cases' this with h_evenSet h_evenSet_compl;
    · have := @h evenSet; simp_all +decide [ DocumentedFree ] ;
      exact absurd this ( evenSet_compl_infinite );
    · assumption;
  have h_evenSet_cofinite : Set.Finite (evenSetᶜ)ᶜ := by
    exact Filter.mem_cofinite.mp (h h_evenSet)
  exact evenSet_infinite ( h_evenSet_cofinite.subset fun x hx => by simpa using hx )

:= by
  constructor;
  · intro hU n hn; have := hU; simp_all +decide [ IsFree ] ;
    exact absurd ( @hU ( { n }ᶜ ) ) ( by simp +decide );
  · cases' Ultrafilter.le_cofinite_or_eq_pure U with h' h' ; aesop;
    grind

:= by
  intro h;

  have h_compl : Sᶜ ∈ (Filter.cofinite : Filter ℕ) := by
    aesop;
  exact absurd ( Filter.inter_mem h ( U.2 h_compl ) ) ( by aesop )

:= by
  obtain ⟨i, hi⟩ : ∃ i ∈ s, A i ∈ U.val := by
    contrapose! hcover; simp_all +decide [ Set.PairwiseDisjoint ] ;

    have h_compl : ∀ i ∈ s, (A i)ᶜ ∈ U.val := by
      exact fun i hi => by simpa using U.1.compl_mem_iff_notMem.mpr ( hcover i hi ) ;
    exact mem_infinite U ( Filter.biInter_mem s.finite_toSet |>.2 h_compl );
  refine' ⟨ i, hi, fun j hj => _ ⟩;
  exact Classical.not_not.1 fun hji => Set.disjoint_iff.1 ( hdisj hj.1 hi.1 hji ) |> fun h => by have := U.1.inter_mem hj.2 hi.2; aesop;

:= by
  obtain ⟨S, hS₁, hS₂⟩ := hA m;
  use S ∩ ⋂ j ∈ Finset.range (m + 1), Classical.choose ( hA j );
  refine' ⟨ _, _, _, _ ⟩;
  · refine' Filter.inter_mem hS₁ _;
    have h_inter : ∀ j ∈ Finset.range (m + 1), Classical.choose (hA j) ∈ U.1 := by
      exact fun j hj => Classical.choose_spec ( hA j ) |>.1;
    convert Filter.biInter_mem ( Finset.finite_toSet ( Finset.range ( m + 1 ) ) ) |>.2 h_inter using 1;
  · intro j hj;
