theorem govUpToOn_of_govAtU {U : Remainder} {L : ℚ⸨X⸩} {a : ℕ → ℝ}
    (h : GovAtU U L a) (K : ℤ) :
    ∃ S : Set ℕ, S ∈ U.1 ∧ QPCF.GovernsUpToOn K S L a

proof:
:= by
  obtain ⟨ S, hS ⟩ := h ( L.order - 1 );
  refine' ⟨ _, Filter.inter_mem hS ( Filter.biInter_mem ( Finset.finite_toSet ( Finset.Icc ( HahnSeries.order L ) K ) ) |>.2 fun n hn => _ ), fun N hN => _ ⟩;
  use fun n => { m : ℕ | 1 ≤ m ∧ |a m - pval L n m| ≤ Classical.choose ( h n ) * ( m : ℝ ) ^ ( - ( n + 1 ) ) };
  · exact Classical.choose_spec ( h n );
  · by_cases hN' : N < HahnSeries.order L;
    · refine' ⟨ S, _ ⟩;
      filter_upwards [ Filter.eventually_gt_atTop 0 ] with n hn hn';
      simp_all +decide [ pval ];
      convert hn'.1.2.trans _ using 1;
      · congr! 2;
        congr! 1;
        ext k; by_cases hk : k ≤ N <;> by_cases hk' : k < HahnSeries.order L <;> simp +decide [ hk, hk' ] ;
        · linarith;
        · exact Or.inl <| HahnSeries.coeff_eq_zero_of_lt_order <| by linarith;
      · gcongr;
        · contrapose! hn';
          exact fun h => absurd h.2 ( by nlinarith [ show ( n : ℝ ) ^ HahnSeries.order L > 0 by positivity, show ( |a n - ∑ᶠ ( k : ℤ ) ( _ : k < HahnSeries.order L ), ( L.coeff k : ℝ ) * ( n ^ k : ℝ ) ⁻¹| : ℝ ) ≥ 0 by positivity, inv_pos.mpr ( show ( n : ℝ ) ^ HahnSeries.order L > 0 by positivity ) ] );
        · rw [ ← zpow_neg ];
          exact zpow_le_zpow_right₀ ( mod_cast hn ) ( by linarith );
    · use Classical.choose ( h N );
      simp +zetaDelta at *;
      exact ⟨ 1, fun n hn₁ hn₂ hn₃ hn₄ => hn₄ N hN' hN |>.2 ⟩

:= by
  have := @beta_caseA_depth;
