    exact ⟨ S, hS₁, _, hS₂, hS₃, hS₄ ⟩;
  · obtain ⟨ m, hdeg ⟩ := QPCF.branch_degree_growth hirr ( QPCF.threadBranch ( F U ) ( threadOf U ) ) B;
