  obtain ⟨ P, Q, hQ, h ⟩ := QPCF.terminating_eq_polyExpansion_div L d hnd hterm;

  have h_error_bound : ∀ k : ℕ, ∃ C : ℝ, {n : ℕ | 1 ≤ n ∧ |a n - (P.eval (n : ℚ) / Q.eval (n : ℚ) : ℝ)| ≤ C * (n : ℝ) ^ (-(k + 1) : ℤ)} ∈ U.1 := by
