    obtain ⟨ D, hD ⟩ := QPCF.ratSeq_governs_expansion P Q hQ k;
    refine' ⟨ C + D, _ ⟩;
    have h_inter : {n : ℕ | 1 ≤ n ∧ |a n - pval L k n| ≤ C * (n : ℝ) ^ (-(k + 1) : ℤ)} ∩ {n : ℕ | 1 ≤ n ∧ |(P.eval (n : ℚ) / Q.eval (n : ℚ) : ℝ) - pval L k n| ≤ D * (n : ℝ) ^ (-(k + 1) : ℤ)} ∈ U.1 := by
      refine' Filter.inter_mem hC _;
      rw [ Filter.eventually_atTop ] at hD;
      obtain ⟨ N, hN ⟩ := hD;
      exact Filter.mem_of_superset ( U.1.compl_mem_iff_notMem.mpr <| finite_not_mem U <| Set.finite_le_nat N ) fun n hn => ⟨ Nat.pos_of_ne_zero fun h => by aesop, by simpa [ h ] using hN n <| le_of_not_ge fun h => hn <| by aesop ⟩;
    refine' Filter.mem_of_superset h_inter _;
    simp +contextual [ Set.subset_def, abs_sub_le_iff ];
    grind;
  refine' ⟨ P, Q, hQ, fun k => _ ⟩;
  obtain ⟨ C, hC ⟩ := h_error_bound k;
  refine' ⟨ _, hC, _ ⟩;
  have hQ_nonzero : ∀ᶠ n : ℕ in atTop, Q.eval (n : ℚ) ≠ 0 := by
    exact ( Q.roots.toFinset.finite_toSet.bddAbove.elim fun N hN => Filter.eventually_atTop.mpr ⟨ ⌊N⌋₊ + 1, fun n hn => by exact fun h => not_lt_of_ge ( hN <| by aesop ) <| Nat.lt_of_floor_lt hn ⟩ );
  filter_upwards [ hQ_nonzero, Filter.eventually_gt_atTop ⌈C⌉₊ ] with n hn hn' ; norm_cast at * ; simp_all +decide [ zpow_add₀, zpow_neg ];
  intro hn₁ hn₂; refine le_trans hn₂ ?_; rw [ mul_inv_le_iff₀ ( by positivity ) ] ; ring_nf; norm_cast;
  simpa [ mul_assoc, mul_comm, mul_left_comm, ne_of_gt ( zero_lt_one.trans_le hn₁ ) ] using Nat.le_ceil C |> le_trans <| mod_cast by nlinarith [ pow_pos ( zero_lt_one.trans_le hn₁ ) k ] ;

:= by
  obtain ⟨d, hd⟩ : ∃ d : ℕ, QPCF.fFract (F U) d = 0 :=
