lemma realizedSeq_eq_pval_of_mem {F : C(Remainder, ℚ⸨X⸩)}
    (St : ∀ m : ℕ, RealizationStage F m) (M : ℤ → ℝ) (E : ℕ → ℕ)
    (n : ℕ) {A : Set ℕ}
    (hA : A ∈ (St (stageOf M E n)).pieces) (hnA : n ∈ A) :
    realizedSeq F St M E n =
      QPCF.pval ((St (stageOf M E n)).val A) ((stageOf M E n : ℕ) : ℤ) n

proof:
:= by
  obtain ⟨B, hB⟩ : ∃ B ∈ (St (stageOf M E n)).pieces, n ∈ B ∧ ∀ C ∈ (St (stageOf M E n)).pieces, n ∈ C → C = B := by
    exact ⟨ A, hA, hnA, fun C hC hC' => Classical.not_not.1 fun h => by have := ( St ( stageOf M E n ) ).disj C hC A hA h; exact this.subset ⟨ hC', hnA ⟩ ⟩;
  unfold realizedSeq; simp +decide [ hB.2.2 A hA hnA ] ;
  split_ifs with h;
  · rw [ hB.2.2 _ h.choose_spec.1 h.choose_spec.2 ];
  · exact False.elim <| h ⟨ A, hA, hnA ⟩

:= by
  exact Set.infinite_of_forall_exists_gt fun n => by
    have := QPCF.ZHat.frequently_ofNat_proj t M;
    rw [ Filter.frequently_atTop ] at this;
    exact Exists.elim ( this ( n + 1 ) ) fun m hm => ⟨ m, hm.2, by linarith ⟩

:= by
  obtain ⟨ L, hL ⟩ := QPCF.order_uniform_bound G;
  obtain ⟨ M, hM ⟩ := QPCF.coeff_uniform_level_range G L N;
  use M;
  intro n hn;
  have h_proj : QPCF.ZHat.proj M (QPCF.ZHat.ofNat n) = QPCF.ZHat.proj M t := by
    exact hn;
  apply QPCF.pval_congr;
  grind

:= by
  have h_compact : IsCompact (Set.univ : Set Remainder) := by
    exact isCompact_univ;
  obtain ⟨ s, hs ⟩ := h_compact.elim_nhds_subcover ( fun U => betaClopen ( betaGovSet a U ( ha U ) K ) ) ( fun U _ => IsOpen.mem_nhds ( betaClopen_isOpen _ ) ( betaGovSet_mem a U ( ha U ) K ) );
  exact ⟨ s, hs.2, finite_betaClopen_cover_cofinite s _ hs.2 ⟩

:= by
  apply QPCF.continuous_laurentSeries_of_eventually_coeff_eq_below;
  intro U K; obtain ⟨ S, hS₁, hS₂ ⟩ := beta_per_cutoff_kernel a ha K U; filter_upwards [ IsOpen.mem_nhds ( show IsOpen ( betaClopen S ) from betaClopen_isOpen S ) hS₁ ] with V hV; intro k hk; exact hS₂ V hV ( betaGermFunction a ha V ) ( betaGermValue_admissible a V ( ha V ) ) k ( by linarith ) |> Eq.symm;

:= by
  intro U;
  convert beta_admissible_germ_governs a U ( betaGermValue a U ( ha U ) ) ( betaGermValue_admissible a U ( ha U ) ) using 1

:= by

      obtain ⟨χ, hχ⟩ := hS;
      use fun n => !χ n; simp_all +decide [ Set.ext_iff ] ;

