lemma eventuallyPeriodic_union {S T : Set ℕ}
    (hS : EventuallyPeriodic S) (hT : EventuallyPeriodic T) :
    EventuallyPeriodic (S ∪ T)

proof:
:= by
      obtain ⟨ χS, rfl, NS, pS, hpS, hS ⟩ := hS
      obtain ⟨ χT, rfl, NT, pT, hpT, hT ⟩ := hT;
      refine' ⟨ fun n => χS n || χT n, _, _ ⟩;
      · grind;
      · refine' ⟨ Max.max NS NT, pS * pT, Nat.mul_pos hpS hpT, fun n hn => _ ⟩;

        have h_periodic_S : χS (n + pS * pT) = χS n := by
          exact Nat.recOn pT ( by norm_num ) fun k hk => by rw [ Nat.mul_succ, ← add_assoc, hS _ ( by nlinarith [ Nat.le_max_left NS NT, Nat.le_max_right NS NT ] ), hk ] ;
        have h_periodic_T : χT (n + pS * pT) = χT n := by
          exact Nat.recOn pS ( by norm_num ) fun k hk => by rw [ Nat.succ_mul, ← add_assoc, hT _ ( by nlinarith [ Nat.le_max_right NS NT ] ), hk ] ;
        aesop

