lemma eventuallyPeriodic_inter {S T : Set ℕ}
    (hS : EventuallyPeriodic S) (hT : EventuallyPeriodic T) :
    EventuallyPeriodic (S ∩ T)

proof:
:= by
      obtain ⟨ χ_S, hχ_S, N_S, p_S, hp_S, h_period_S ⟩ := hS
      obtain ⟨ χ_T, hχ_T, N_T, p_T, hp_T, h_period_T ⟩ := hT
      use fun n => χ_S n && χ_T n;
      refine' ⟨ _, N_S + N_T, p_S * p_T, mul_pos hp_S hp_T, _ ⟩;
      · grind;
      · intro n hn
        have h_period_S_n : χ_S (n + p_S * p_T) = χ_S n := by
          exact Nat.recOn p_T ( by norm_num ) fun k hk => by rw [ Nat.mul_succ, ← add_assoc, h_period_S _ ( by nlinarith ), hk ] ;
        have h_period_T_n : χ_T (n + p_S * p_T) = χ_T n := by
          exact Nat.recOn p_S ( by norm_num ) fun k hk => by rw [ Nat.succ_mul, ← add_assoc, h_period_T _ ( by nlinarith ), hk ] ;
        simp [h_period_S_n, h_period_T_n]

:= by
  convert B.eventuallyPeriodic_mem _;
  exact ⟨ fun _ => Bool.true, by norm_num, 0, 1, by norm_num ⟩

:= by
  by_contra h_contra;

  have h_union : ∃ T : Finset ℕ, S = ⋃ n ∈ T, {n} := by
    exact ⟨ hS.toFinset, by simpa ⟩;

  have h_singleton_mem : ∀ n : ℕ, {n} ∈ B := by
    intro n
    have h_singleton_periodic : EventuallyPeriodic {n} := by
      use fun m => m = n;
      exact ⟨ by aesop, n + 1, 1, by norm_num, fun m hm => by aesop ⟩
    exact B.eventuallyPeriodic_mem h_singleton_periodic;

  have h_union_mem : ∀ (T : Finset ℕ), (⋃ n ∈ T, {n}) ∈ B := by
    intro T;
    induction' T using Finset.induction with n T hnT ih;
    · convert B.compl_mem ( univ_mem B ) using 1 ; aesop;
    · convert B.union_mem ( h_singleton_mem n ) ih using 1 ; aesop;
  exact h_contra <| h_union.choose_spec ▸ h_union_mem _

:= by
  obtain h | h := U.decisive ⟨ Set.univ, QPCF.Gamma.univ_mem B ⟩;
  · exact h;
  · convert U.superset_mem _ h;
    exact Set.subset_univ _

:= by
      constructor <;> intro h;
      · intro h';
        exact U.empty_not_mem ( by simpa using U.inter_mem h' h );
      · exact U.decisive S |> Or.resolve_left <| h

:= by
  intro U V hUV;
  apply GammaUltrafilter.ext;
  simp_all +decide [ funext_iff, GammaUltrafilter.code ]

:= by

  intro U V hUV;
  apply Subtype.ext; apply GammaUltrafilter.ext; simp_all +decide [ funext_iff, GammaUltrafilter.code ] ;
  convert hUV using 1;
  simp +decide [ remainderCode, GammaUltrafilter.code ]

:= by
  refine' isClosed_iff_nhds.2 fun f hf => _;

  have h_conditions : (∀ S : BSet B, S.1ᶜ.Finite → f S = true) ∧ (f ⟨∅, empty_mem B⟩ = false) ∧ (∀ S T : BSet B, f S = true → f T = true → f ⟨S.1 ∩ T.1, B.inter_mem S.2 T.2⟩ = true) ∧ (∀ S T : BSet B, S.1 ⊆ T.1 → f S = true → f T = true) ∧ (∀ S : BSet B, f S = true ∨ f ⟨S.1ᶜ, B.compl_mem S.2⟩ = true) := by
    refine' ⟨ _, _, _, _, _ ⟩;
    · intro S hS;
      contrapose! hf;
      refine' ⟨ { g : BSet B → Bool | g S = false }, _, _ ⟩ <;> simp_all +decide [ Set.ext_iff ];
      · rw [ nhds_pi ];
        simp +decide [ Filter.mem_pi, hf ];
        exact ⟨ { S }, by simp +decide, fun _ => { f ‹_› }, by aesop ⟩;
      · intro x hx U hU; have := U.2 S hS; simp_all +decide [ funext_iff, remainderCode ] ;
        exact absurd ( hU _ S.2 ) ( by simp +decide [ hx, GammaUltrafilter.code, this ] );
    · contrapose! hf;
      refine' ⟨ { g : BSet B → Bool | g ⟨ ∅, empty_mem B ⟩ = true }, _, _ ⟩ <;> simp_all +decide [ Set.ext_iff ];
      · refine' IsOpen.mem_nhds _ _ <;> norm_num [ hf ];
        refine' isOpen_pi_iff.mpr _;
        exact fun g hg => ⟨ { ⟨ ∅, empty_mem B ⟩ }, fun _ => { true }, by aesop ⟩;
      · intro x hx y hy; have := congr_fun hy ⟨ ∅, empty_mem B ⟩ ; simp_all +decide [ GammaUltrafilter.empty_not_mem ] ;
        have := y.1.empty_not_mem; simp_all +decide [ remainderCode ] ;
        unfold GammaUltrafilter.code at hy; aesop;
    · intro S T hS hT;
      contrapose! hf;
      refine' ⟨ { g : BSet B → Bool | g S = true ∧ g T = true ∧ g ⟨ S.1 ∩ T.1, B.inter_mem S.2 T.2 ⟩ = false }, _, _ ⟩ <;> simp_all +decide [ Set.ext_iff ];
      · rw [ mem_nhds_iff ];
        refine' ⟨ { g : BSet B → Bool | g S = true ∧ g T = true ∧ g ⟨ S.1 ∩ T.1, B.inter_mem S.2 T.2 ⟩ = false }, _, _, _ ⟩ <;> norm_num [ hS, hT, hf ];

        have h_open : IsOpen {g : BSet B → Bool | g S = true} ∧ IsOpen {g : BSet B → Bool | g T = true} ∧ IsOpen {g : BSet B → Bool | g ⟨S.1 ∩ T.1, B.inter_mem S.2 T.2⟩ = false} := by
          refine' ⟨ _, _, _ ⟩;
          · 
            have h_open : IsOpen {g : BSet B → Bool | g S = true} := by
              have h_cont : Continuous (fun g : BSet B → Bool => g S) := by
                exact continuous_apply S
              exact h_cont.isOpen_preimage { true } ( by simp +decide );
            exact h_open;
          · rw [ isOpen_pi_iff ];
            exact fun g hg => ⟨ { T }, fun _ => { true }, by aesop ⟩;
          · rw [ isOpen_pi_iff ];
            intro g hg; use { ⟨ S.1 ∩ T.1, B.inter_mem S.2 T.2 ⟩ } ; use fun _ => { false } ; aesop;
        exact IsOpen.inter h_open.1 ( IsOpen.inter h_open.2.1 h_open.2.2 );
      · intro x hxS hxT hxST U hU; have := congr_fun hU S; have := congr_fun hU T; have := congr_fun hU ⟨ S.1 ∩ T.1, B.inter_mem S.2 T.2 ⟩ ; simp_all +decide [ GammaUltrafilter.inter_mem ] ;
        have := U.1.inter_mem ( show U.1.Mem S from by
                                  have := congr_fun hU S; simp_all +decide [ remainderCode ] ;
                                  unfold GammaUltrafilter.code at hU; aesop; ) ( show U.1.Mem T from by
                                                                  have := congr_fun hU T; simp_all +decide [ remainderCode ] ;
                                                                  unfold GammaUltrafilter.code at hU; aesop; ) ; simp_all +decide [ remainderCode ] ;
        unfold GammaUltrafilter.code at hU; aesop;
    · intro S T hST hS;
      contrapose! hf;
      refine' ⟨ { g : BSet B → Bool | g S = true ∧ g T = false }, _, _ ⟩ <;> simp_all +decide [ Set.ext_iff ];
      · refine' IsOpen.mem_nhds _ _;
        · 
          have h_open : IsOpen {g : BSet B → Bool | g S = true} ∧ IsOpen {g : BSet B → Bool | g T = false} := by
            constructor <;> rw [ isOpen_pi_iff ];
            · exact fun g hg => ⟨ { S }, fun _ => { true }, by aesop ⟩;
            · exact fun g hg => ⟨ { T }, fun _ => { false }, by aesop ⟩;
          exact h_open.1.inter h_open.2;
        · aesop;
      · intro x hxS hxT U hU; have := congr_fun hU S; have := congr_fun hU T; simp_all +decide [ GammaUltrafilter.code ] ;
        have := U.1.superset_mem hST; simp_all +decide [ remainderCode ] ;
        unfold GammaUltrafilter.code at hU; aesop;
    · intro S
      by_contra h_contra
      push_neg at h_contra
      generalize_proofs at *;
      obtain ⟨ g, hg ⟩ := hf ( { g : BSet B → Bool | g S = false ∧ g ⟨ ( S : Set ℕ )ᶜ, by assumption ⟩ = false } ) ( by
        rw [ nhds_pi ];
        simp +decide [ Filter.mem_pi, h_contra ];
        use {S, ⟨(S : Set ℕ)ᶜ, by assumption⟩};
        refine' ⟨ Set.toFinite _, fun x => { f x }, _, _ ⟩ <;> simp_all +decide [ Set.subset_def ] )
      generalize_proofs at *;
      obtain ⟨ U, rfl ⟩ := hg.2; have := U.1.decisive S; simp_all +decide ;
      cases this <;> simp_all +decide [ remainderCode ]; all_goals unfold GammaUltrafilter.code at hg; aesop;

  obtain ⟨U, hU⟩ : ∃ U : GammaUltrafilter B, ∀ S : BSet B, U.Mem S = (f S = true) := by
    refine' ⟨ ⟨ fun S => f S = true, _, _, _, _ ⟩, _ ⟩ <;> aesop;
  use ⟨U, by
    intro S hS; specialize h_conditions; have := h_conditions.1 S hS; aesop;⟩
  generalize_proofs at *;
  ext S; simp [remainderCode, hU];
  unfold GammaUltrafilter.code; aesop;

:= by
  constructor;
  · 
    have h_closed : IsClosed {U : gammaRemainder B | U.1.Mem S} := by
      have h_preimage : {U : gammaRemainder B | U.1.Mem S} = (remainderCode B) ⁻¹' {x : BSet B → Bool | x S = true} := by
        ext; simp [remainderCode, GammaUltrafilter.code]
      exact h_preimage ▸ IsClosed.preimage ( show Continuous ( remainderCode B ) from continuous_induced_dom ) ( isClosed_eq ( continuous_apply _ ) continuous_const );
    exact h_closed;
  · convert ( isOpen_discrete { true } ) |> ( ·.preimage ( show Continuous fun U : gammaRemainder B => U.1.code S from ?_ ) ) using 1;
    · ext; simp [basicClopen, GammaUltrafilter.code];
    · convert continuous_apply S |> Continuous.comp <| continuous_induced_dom

:= by
      refine' TopologicalSpace.isTopologicalBasis_of_isOpen_of_nhds _ _ <;> simp_all +decide [ basicClopen ];
      · exact fun u x hx hu => by simpa [ hu ] using ( basicClopen_isClopen B ⟨ x, hx ⟩ ) |>.2;
      · intro U u hu hU
        obtain ⟨S, hS⟩ : ∃ S : Finset (BSet B), (remainderCode B) ⁻¹' {x : BSet B → Bool | ∀ s ∈ S, x s = (remainderCode B U) s} ⊆ u := by
          obtain ⟨ t, ht, rfl ⟩ := hU; simp_all +decide [ Set.subset_def ] ; (
          rw [ isOpen_pi_iff ] at ht; obtain ⟨ S, hS ⟩ := ht ( remainderCode B U ) hu; use S; aesop;)
        generalize_proofs at *; (

        obtain ⟨a, ha⟩ : ∃ a : BSet B, (∀ s ∈ S, (remainderCode B U) s = true → a.1 ⊆ s.1) ∧ (∀ s ∈ S, (remainderCode B U) s = false → a.1 ⊆ s.1ᶜ) ∧ U.1.Mem a := by
          have h_inter : ∀ (T : Finset (BSet B)), (∀ t ∈ T, U.1.Mem t) → ∃ a : BSet B, (∀ t ∈ T, a.1 ⊆ t.1) ∧ U.1.Mem a := by
            intro T hT; induction' T using Finset.induction with t T ih <;> simp_all +decide [ Finset.subset_iff ] ;
            · exact ⟨ Set.univ, univ_mem B, U.1.univ_mem ⟩;
            · obtain ⟨ a, ha₁, ha₂ ⟩ := ‹∃ a : Set ℕ, ( ∀ a_1 : Set ℕ, ∀ b : a_1 ∈ B, ⟨ a_1, b ⟩ ∈ T → a ⊆ a_1 ) ∧ ∃ x : a ∈ B, ( U.1.Mem ⟨ a, x ⟩ ) ›; use a ∩ t.1; simp_all +decide [ Set.subset_def ] ;
              exact ⟨ B.inter_mem ha₂.choose t.2, U.1.inter_mem ha₂.choose_spec hT.1 ⟩;
            · exact Classical.decEq _
          generalize_proofs at *; (
          obtain ⟨a, ha⟩ : ∃ a : BSet B, (∀ s ∈ S, (remainderCode B U) s = true → a.1 ⊆ s.1) ∧ (∀ s ∈ S, (remainderCode B U) s = false → a.1 ⊆ s.1ᶜ) ∧ U.1.Mem a := by
            have h_T : ∀ s ∈ S, U.1.Mem (if (remainderCode B U) s then s else ⟨s.1ᶜ, B.compl_mem s.2⟩) := by
              intro s hs; split_ifs <;> simp_all +decide [ remainderCode ] ;
              · unfold GammaUltrafilter.code at *; aesop;
              · have := U.1.decisive s; simp_all +decide [ GammaUltrafilter.code ] ;
            obtain ⟨a, ha⟩ : ∃ a : BSet B, (∀ s ∈ S, a.1 ⊆ (if (remainderCode B U) s then s else ⟨s.1ᶜ, B.compl_mem s.2⟩).1) ∧ U.1.Mem a := by
              convert h_inter ( S.image ( fun s => if remainderCode B U s = true then s else ⟨ s.1ᶜ, B.compl_mem s.2 ⟩ ) ) _ using 1 <;> simp_all +decide [ Finset.subset_iff ];
              · grind;
              · exact Classical.decEq _;
              · grind +ring
            generalize_proofs at *; (
            exact ⟨ a, fun s hs hs' => by simpa [ hs' ] using ha.1 s hs, fun s hs hs' => by simpa [ hs' ] using ha.1 s hs, ha.2 ⟩)
          generalize_proofs at *; (
          use a))
        generalize_proofs at *; (
        refine' ⟨ a.1, a.2, ha.2.2, fun V hV => hS _ ⟩ ; simp_all +decide [ remainderCode ] ;
        intro s hs hs'; by_cases h : ( U.1.code ⟨ s, hs ⟩ ) = true <;> simp_all +decide [ GammaUltrafilter.code ] ;
        · exact V.1.superset_mem ( ha.1 _ _ hs' h ) hV;
        · intro H; have := ha.2.1 s hs hs' h; have := this; simp_all +decide [ Set.subset_def ] ;
          have := V.1.compl_mem_iff_not_mem ⟨ s, hs ⟩ ; simp_all +decide [ GammaUltrafilter.code ] ;
          exact this ( V.1.superset_mem ( show a.1 ⊆ sᶜ from fun x hx => by have := ha.2.1 s hs hs' h x hx; aesop ) hV )))

:= by
      contrapose! hS;
      convert finite_not_mem B U S hS using 1

:= by

      have h_exists : ∃ i ∈ s, U.1.Mem (A i) := by
        by_contra h_contra;

        have h_inter : U.1.Mem ⟨(⋃ i ∈ s, (A i).1)ᶜ ∩ Set.univ, by
          convert B.compl_mem ( B.union_mem ( show ( ⋃ i ∈ s, ( A i : Set ℕ ) ) ∈ B from ?_ ) ( show ( ∅ : Set ℕ ) ∈ B from empty_mem B ) ) using 1 ; aesop;
          have h_union : ∀ (s : Finset ι), (⋃ i ∈ s, (A i).1) ∈ B := by
            intro s; induction s using Finset.induction <;> simp_all +decide ;
            · exact QPCF.Gamma.empty_mem B;
            · exact B.union_mem ( A _ |>.2 ) ‹_›;
            · exact Classical.decEq ι;
          exact h_union s⟩ := by
          all_goals generalize_proofs at *;
          have h_inter : ∀ (s : Finset ι), (∀ i ∈ s, U.1.Mem ⟨(A i).1ᶜ, B.compl_mem (A i).2⟩) → U.1.Mem ⟨(⋃ i ∈ s, (A i).1)ᶜ ∩ Set.univ, by
            induction s using Finset.induction <;> simp_all +decide [ Set.compl_iUnion ];
            · exact QPCF.Gamma.univ_mem B;
            · exact B.inter_mem ( B.compl_mem ( A _ |>.2 ) ) ‹_›;
            · exact Classical.decEq ι⟩ := by
            intro s hs; induction s using Finset.induction <;> simp_all +decide [ Set.compl_iUnion ] ;
            all_goals generalize_proofs at *;
            · exact U.1.univ_mem;
            · exact U.1.inter_mem hs.1 ‹_›;
            · exact Classical.decEq ι
          generalize_proofs at *;
          exact h_inter s fun i hi => by simpa using U.1.compl_mem_iff_not_mem _ |>.2 fun h => h_contra ⟨ i, hi, h ⟩ ;
        generalize_proofs at *;
        exact absurd ( mem_infinite B U _ h_inter ) ( Set.not_infinite.mpr <| hcover.subset fun x hx => hx.1 );
      obtain ⟨ i, hi, hi' ⟩ := h_exists; use i; refine' ⟨ ⟨ hi, hi' ⟩, _ ⟩ ; intro j hj; cases eq_or_ne i j <;> simp_all +decide [ Finset.disjoint_left, Set.PairwiseDisjoint ] ;
      have := hdisj hi hj.1 ‹_›; simp_all +decide [ Set.disjoint_left ] ;
      exact False.elim ( finite_not_mem B U ⟨ _, B.inter_mem ( A i |>.2 ) ( A j |>.2 ) ⟩ ( Set.Finite.subset ( Set.finite_singleton 0 ) ( by aesop ) ) ( by simpa using U.1.inter_mem hi' hj.2 ) )

:= by

      obtain ⟨F, hF⟩ : ∃ F : Ultrafilter ℕ, S ∈ F.sets ∧ ∀ T : Set ℕ, Tᶜ.Finite → T ∈ F.sets := by
        have h_finite_inter_nonempty : ∀ T : Finset (Set ℕ), (↑T : Set (Set ℕ)) ⊆ {S} ∪ {T : Set ℕ | Tᶜ.Finite} → (⋂₀ (↑T : Set (Set ℕ))).Nonempty := by
          intro T hT;

          obtain ⟨x, hxS, hxT⟩ : ∃ x ∈ S, ∀ T' ∈ T, T' ≠ S → x ∈ T' := by
            have h_finite_inter : Set.Finite (⋃ T' ∈ T, ⋃ (_ : T' ≠ S), T'ᶜ) := by
              exact Set.Finite.biUnion ( Finset.finite_toSet T ) fun x hx => by cases hT hx <;> aesop;
            exact Exists.elim ( hS.diff h_finite_inter |> Set.Infinite.nonempty ) fun x hx => ⟨ x, hx.1, fun T' hT' hT'' => by_contra fun hx' => hx.2 <| Set.mem_iUnion₂.mpr ⟨ T', hT', by aesop ⟩ ⟩;
          exact ⟨ x, by intro T' hT'; by_cases h : T' = S <;> aesop ⟩;
        obtain ⟨ F, hF ⟩ := Ultrafilter.exists_ultrafilter_of_finite_inter_nonempty ( { S } ∪ { T : Set ℕ | Tᶜ.Finite } ) h_finite_inter_nonempty;
        exact ⟨ F, hF <| Set.mem_union_left _ <| Set.mem_singleton _, fun T hT => hF <| Set.mem_union_right _ hT ⟩;
      constructor;
      swap;
      constructor;
      rotate_left;
      constructor;
      rotate_left;
      case Mem => exact fun S => S.1 ∈ F.sets;
      exact fun { S T } hS hT => Filter.inter_mem hS hT;
      exact fun { S T } hST hS => Filter.mem_of_superset hS hST;
      exact fun S => F.mem_or_compl_mem _;
      exact hF.1;
      exact fun S hS => hF.2 _ hS;
      exact fun h => by simpa using F.empty_notMem h;

:= by

      by_contra h_contra
