:= by

  obtain ⟨M, hM⟩ : ∃ M : ℕ, ∀ m ≥ M, ∀ n ≥ M, (polyContDen (gammaCanonicalPQ B a U hA) (m + 1)).natDegree ≥ Int.toNat D + 1 ∧ (polyContDen (gammaCanonicalPQ B a U hA) (n + 1)).natDegree ≥ Int.toNat D + 1 := by
