lemma truncSum_congr {F G : LaurentSeries ℚ} {N : ℤ}
    (h : ∀ k : ℤ, k ≤ N → F.coeff k = G.coeff k) (n : ℕ) :
    truncSum F N n = truncSum G N n

proof:
:= by
  unfold truncSum;
  by_cases hF : order F ≤ N <;> by_cases hG : order G ≤ N <;> simp_all +decide;
  · have h_sum_eq : ∑ x ∈ Finset.Icc (min (order F) (order G)) N, (F.coeff x : ℝ) * (n : ℝ) ^ (-x) = ∑ x ∈ Finset.Icc (min (order F) (order G)) N, (G.coeff x : ℝ) * (n : ℝ) ^ (-x) := by
      exact Finset.sum_congr rfl fun x hx => by rw [ h x ( Finset.mem_Icc.mp hx |>.2 ) ] ;
    convert h_sum_eq using 1;
    · rw [ ← Finset.sum_subset ( show Finset.Icc ( order F ) N ⊆ Finset.Icc ( min ( order F ) ( order G ) ) N from fun x hx => Finset.mem_Icc.mpr ⟨ by cases min_cases ( order F ) ( order G ) <;> linarith [ Finset.mem_Icc.mp hx ], by cases min_cases ( order F ) ( order G ) <;> linarith [ Finset.mem_Icc.mp hx ] ⟩ ) ] ; aesop;
      simp +zetaDelta at *;
      exact fun x hx₁ hx₂ hx₃ => Or.inl <| HahnSeries.coeff_eq_zero_of_lt_order <| lt_of_not_ge fun hx₄ => by linarith [ hx₃ hx₄ ] ;
    · rw [ ← Finset.sum_subset ( show Finset.Icc ( order G ) N ⊆ Finset.Icc ( min ( order F ) ( order G ) ) N from Finset.Icc_subset_Icc ( min_le_right _ _ ) le_rfl ) ] ; aesop;
      simp +zetaDelta at *;
      exact fun x hx₁ hx₂ hx₃ => Or.inl <| HahnSeries.coeff_eq_zero_of_lt_order <| lt_of_not_ge fun hx₄ => by linarith [ hx₃ hx₄ ] ;
  · rw [ Finset.sum_eq_zero ];
    intro k hk; specialize h k ( Finset.mem_Icc.mp hk |>.2 ) ; simp_all +decide ;
    exact Or.inl <| HahnSeries.coeff_eq_zero_of_lt_order <| by linarith;
  · contrapose! hF;
    obtain ⟨ k, hk ⟩ := Finset.exists_ne_zero_of_sum_ne_zero hF.symm;
    exact le_trans ( HahnSeries.order_le_of_coeff_ne_zero ( show F.coeff k ≠ 0 from by aesop ) ) ( Finset.mem_Icc.mp hk.1 |>.2 )

:= by
  intro N hN;

  obtain ⟨m, hm1, hmN⟩ : ∃ m, 1 ≤ m ∧ (N : ℤ) < edeg p m := by
    have := deg_to_infty ( hlead_of_H1 h1 ) hH2;
    exact Filter.eventually_atTop.mp ( this.eventually_gt_atTop ( Int.toNat N ) ) |> fun ⟨ m, hm ⟩ ↦ ⟨ m + 1, by linarith, by linarith! [ Int.self_le_toNat N, hm ( m + 1 ) ( by linarith ) ] ⟩;

  have h_real_err : (fun n => a n - pev (hC p m) n / pev (kC p m) n) =O[atTop] (fun n : ℕ => (n : ℝ) ^ (-(2 * (edeg p m) : ℤ))) :=
    real_err_isBigO h1 m hm1

  have h_tail : (fun n => pev (hC p m) n / pev (kC p m) n - truncSum (iota (hC p m) / iota (kC p m)) N n) =O[atTop] (fun n : ℕ => (n : ℝ) ^ (-(N + 1))) := by
    apply tail_isBigO;
    exact Q_lead_pos ( hlead_of_H1 h1 ) m;

  have h_truncSum_congr : ∀ n : ℕ, truncSum F N n = truncSum (iota (hC p m) / iota (kC p m)) N n := by
    intro n; apply truncSum_congr; intro k hk; exact hFcoeff m k (by linarith) |> fun h => by
      exact h.trans ( by rw [ Lm_eq ] );
  convert h_real_err.trans _ |> Asymptotics.IsBigO.add <| h_tail using 1;
  · exact funext fun n => by rw [ h_truncSum_congr n ] ; ring;
  · refine' Asymptotics.IsBigO.of_bound 1 _;
    filter_upwards [ Filter.eventually_gt_atTop 0 ] with n hn using by rw [ one_mul ] ; rw [ Real.norm_of_nonneg ( by positivity ), Real.norm_of_nonneg ( by positivity ) ] ; exact zpow_le_zpow_right₀ ( mod_cast hn ) ( by linarith ) ;

|x - contNum (fun j => realPQ j x) (k+1) / contDen (fun j => realPQ j x) (k+1)|
