             * (contDen (fun j => realPQ j x) (k+1) * realGaussIter (k+1) x
                + contDen (fun j => realPQ j x) k)| := by
  by_cases h : contDen ( fun j => realPQ j x ) ( k + 1 ) = 0 <;> simp_all +decide [ mul_div_cancel₀, sub_eq_iff_eq_add ];
  · have h_pos : ∀ j ≤ k, 1 ≤ realPQ (j + 1) x := by
      intro j hj; have := hx ( j + 1 ) ( by linarith ) ; simp_all +decide [ realGaussIter_succ_fract ] ;
      unfold realPQ; simp +decide [ this, realGaussIter_succ_fract ] ;
      exact_mod_cast Int.floor_pos.mpr ( by nlinarith [ Int.fract_nonneg ( realGaussIter j x ), Int.fract_lt_one ( realGaussIter j x ), mul_inv_cancel₀ this, show ( Int.fract ( realGaussIter j x ) : ℝ ) < 1 from Int.fract_lt_one _ ] );
    have h_pos : ∀ j ≤ k, 0 < contDen (fun j => realPQ j x) (j + 1) ∧ 0 ≤ contDen (fun j => realPQ j x) j := by
      intro j hj
      induction' j with j ih;
      · exact ⟨ by norm_num [ contDen ], by norm_num [ contDen ] ⟩;
      · exact ⟨ by rw [ contDen_succ2 ] ; exact add_pos_of_pos_of_nonneg ( mul_pos ( by linarith [ h_pos j ( by linarith ) ] ) ( ih ( by linarith ) |>.1 ) ) ( ih ( by linarith ) |>.2 ), ih ( by linarith ) |>.1.le ⟩;
    exact absurd h ( ne_of_gt ( h_pos k le_rfl |>.1 ) );
  · have := cont_value ( fun j => realPQ j x ) ( fun j => realGaussIter j x ) k ?_ ?_ <;> simp_all +decide [ sub_eq_iff_eq_add ];
    · field_simp;
