  intro N;
  convert BigOpowOn.add ( hf N ) ( hg N ) using 1;
  ext n; rw [ pval_add ] ; ring;

statement:
theorem GovernsOn.mul {S : Set ℕ} {f g : ℚ⸨X⸩} {a b : ℕ → ℝ}
    (hf : GovernsOn S f a) (hg : GovernsOn S g b) :
    GovernsOn S (f * g) (fun n => a n * b n)

proof:
:= by
  intro N
  set M' := (Int.natAbs N) + (Int.natAbs f.order) + (Int.natAbs g.order) + 1 with hM';
  convert BigOpowOn.add ( BigOpowOn.add ( BigOpowOn.add ( pval_mul_sub_bigOpow f g N M' _ _ _ |> BigOpow.toOn S ) ( BigOpowOn.mono ( BigOpowOn.mul ( pval_bigOpow f M' |> BigOpow.toOn S ) ( hg M' ) ) _ ) ) ( BigOpowOn.mono ( BigOpowOn.mul ( hf M' ) ( pval_bigOpow g M' |> BigOpow.toOn S ) ) _ ) ) ( BigOpowOn.mono ( BigOpowOn.mul ( hf M' ) ( hg M' ) ) _ ) using 1;
  grind;
  all_goals omega;

:= by
  intro N
  obtain ⟨ C, hC ⟩ := hf N;
  use C;
  filter_upwards [ hC ] with n hn hn' using by rw [ abs_le ] ; constructor <;> linarith [ abs_le.mp ( hn hn' ), show pval ( -f ) N n = -pval f N n from pval_neg f N n ] ;

:= by

  have h_diff : GovernsOn S (f - g) (fun _ => 0) := by
    convert GovernsOn.add hf ( GovernsOn.neg hg ) using 1 ; ext ; norm_num ; ring;
    norm_num;
  by_contra h_nonzero;
  have h_coeff_nonzero : (f - g).coeff (f - g).order ≠ 0 := by
    grind +suggestions
  have h_order : ∃ C : ℝ, ∀ᶠ n in atTop, n ∈ S → |(f - g).coeff (f - g).order * (n : ℝ) ^ (-(f - g).order)| ≤ C * (n : ℝ) ^ (-( (f - g).order + 1 )) := by
    obtain ⟨ C, hC ⟩ := h_diff ( f - g |> order );
    use C; filter_upwards [ hC ] with n hn hnS; simp_all +decide [ pval_eq_finset_sum ] ;
  have h_contradiction : ∃ C : ℝ, ∀ᶠ n in atTop, n ∈ S → |(f - g).coeff (f - g).order| * (n : ℝ) ≤ C := by
    obtain ⟨ C, hC ⟩ := h_order; use C; filter_upwards [ hC, Filter.eventually_gt_atTop 0 ] with n hn hn'; intro hn''; specialize hn hn''; simp_all +decide [ abs_mul, abs_of_nonneg ] ;
    convert mul_le_mul_of_nonneg_right hn ( show ( 0 : ℝ ) ≤ n ^ ( order ( f - g ) + 1 ) by positivity ) using 1 ; ring;
    · rw [ mul_assoc, ← zpow_neg, ← zpow_add₀ ( by positivity ) ] ; norm_num;
    · rw [ mul_assoc, ← zpow_add₀ ( by positivity ) ] ; ring ; norm_num [ hn'.ne' ];
  obtain ⟨ C, hC ⟩ := h_contradiction; simp_all +decide [ Filter.frequently_atTop ] ;
  obtain ⟨ a, ha ⟩ := hC; rcases hS ( a + ⌈C / |(f.coeff (order (f - g)) - g.coeff (order (f - g)) : ℝ)|⌉₊ + 1 ) with ⟨ b, hb₁, hb₂ ⟩ ; have := ha b ( by linarith ) hb₂ ; norm_num at this;
  nlinarith [ Nat.le_ceil ( C / |(f.coeff (order (f - g)) - g.coeff (order (f - g)) : ℝ)| ), show ( b : ℝ ) ≥ a + ⌈C / |(f.coeff (order (f - g)) - g.coeff (order (f - g)) : ℝ)|⌉₊ + 1 by exact_mod_cast hb₁, abs_pos.mpr ( show ( f.coeff ( order ( f - g ) ) - g.coeff ( order ( f - g ) ) : ℝ ) ≠ 0 by simpa [ sub_eq_iff_eq_add ] using h_coeff_nonzero ), mul_div_cancel₀ C ( ne_of_gt ( abs_pos.mpr ( show ( f.coeff ( order ( f - g ) ) - g.coeff ( order ( f - g ) ) : ℝ ) ≠ 0 by simpa [ sub_eq_iff_eq_add ] using h_coeff_nonzero ) ) ) ]

:= by
  intro r;
  convert Governs.toOn ( classSet M r ) _;
  convert Governs.zero

:= by
  intro r;
  convert ( Governs.one ).toOn ( classSet M r ) using 1

statement:
theorem GovByMod.add {L L' : ZMod M → ℚ⸨X⸩} {a b : ℕ → ℝ}
    (hf : GovByMod M L a) (hg : GovByMod M L' b) :
    GovByMod M (fun r => L r + L' r) (fun n => a n + b n)

theorem GovByMod.mul {L L' : ZMod M → ℚ⸨X⸩} {a b : ℕ → ℝ}
    (hf : GovByMod M L a) (hg : GovByMod M L' b) :
    GovByMod M (fun r => L r * L' r) (fun n => a n * b n)

proof:
:= by
  intro r;
  convert GovernsOn.neg ( hf r ) using 1

:= by
  funext r;
  apply GovernsOn.unique (frequently_classSet M r) (hf r) (hg r)

:= by
  convert Classical.not_not.1 _;
  intro h_neg
  obtain ⟨k, hk⟩ : ∃ k : ℤ, ¬BigOpow (fun n => a n - b n) (-k) := by
    convert Classical.not_forall.1 ( negligible_iff_bigOpow.not.mp h_neg ) using 1;

  have h_const_r : ∀ r : ZMod M, ∃ C_r : ℝ, ∀ᶠ n in atTop, n ∈ classSet M r → |a n - b n| ≤ C_r * (n : ℝ) ^ (-k) := by
    intro r
    obtain ⟨C_r, hC_r⟩ : ∃ C_r : ℝ, ∀ᶠ n in atTop, n ∈ classSet M r → |a n - pval (L r) (k - 1) n| ≤ C_r * (n : ℝ) ^ (-(k - 1 + 1)) := by
      exact ha r ( k - 1 )
    obtain ⟨C_r', hC_r'⟩ : ∃ C_r' : ℝ, ∀ᶠ n in atTop, n ∈ classSet M r → |b n - pval (L r) (k - 1) n| ≤ C_r' * (n : ℝ) ^ (-(k - 1 + 1)) := by
      exact hb r ( k - 1 )
    use C_r + C_r';
    filter_upwards [ hC_r, hC_r' ] with n hn hn' hn'' using by rw [ add_mul ] ; exact abs_le.mpr ⟨ by ring_nf at *; linarith [ abs_le.mp ( hn hn'' ), abs_le.mp ( hn' hn'' ) ], by ring_nf at *; linarith [ abs_le.mp ( hn hn'' ), abs_le.mp ( hn' hn'' ) ] ⟩ ;
  choose C_r hC_r using h_const_r;
  refine' hk ⟨ Finset.univ.sup' Finset.univ_nonempty fun r => |C_r r|, _ ⟩;
  filter_upwards [ Filter.eventually_ge_atTop 1, Filter.eventually_all.mpr fun r => hC_r r ] with n hn hn' using le_trans ( hn' _ <| by aesop ) <| mul_le_mul_of_nonneg_right ( le_trans ( le_abs_self _ ) <| Finset.le_sup' ( fun r => |C_r r| ) <| Finset.mem_univ _ ) <| by positivity;

:= by
  intro r N; specialize ha r N; exact (by
  obtain ⟨ C, hC ⟩ := ha; obtain ⟨ D, hD ⟩ := negligible_iff_bigOpow.mp hab ( N + 1 ) ; use C + D; filter_upwards [ hC, hD ] with n hn hn' ; simp_all +decide [ sub_eq_add_neg ] ;
  intro hn''; rw [ add_mul ] ; exact abs_le.mpr ⟨ by linarith [ abs_le.mp ( hn hn'' ), abs_le.mp hn' ], by linarith [ abs_le.mp ( hn hn'' ), abs_le.mp hn' ] ⟩ ;);

:= by

  use fun n => borelSeq (L (n : ZMod M)) n;
  intro r; exact (Governs.toOn (classSet M r) (governs_borelSeq (L r))).congr_seq (fun n hn => by simp [hn.symm])

:= by
  refine' le_antisymm _ _;
  · refine' HahnSeries.order_le_of_coeff_ne_zero _;
    simp +decide [ oneAddPow, oneAddPowPS ];
    simp +decide [ ofPowerSeries ];
    simp +decide [ embDomain, HahnSeries.toPowerSeries ];
    grind;
  · 
    have h_support : ∀ k : ℤ, k < 0 → (oneAddPow α).coeff k = 0 := by
      intro k hk; unfold oneAddPow;
      simp +decide [ ofPowerSeries ];
      simp +decide [ embDomain ];
      grind;
    grind +suggestions

:= by
  convert pval_eq_finset_sum ( oneAddPow α ) N n using 1;
  rw [ show ( Finset.Icc ( HahnSeries.order ( oneAddPow α ) ) ( N : ℤ ) ) = Finset.image ( fun i : ℕ => ( i : ℤ ) ) ( Finset.range ( N + 1 ) ) from ?_, Finset.sum_image ] <;> norm_num;
  · congr! 2;
    convert Ring.map_choose ( algebraMap ℚ ℝ ) α ‹_› |> Eq.symm;
    convert oneAddPow_coeff_nat α ‹_› using 1;
  · ext ( _ | i ) <;> simp +decide [ oneAddPow_order ]

:= by
  have h_taylor : HasFPowerSeriesAt (fun x : ℝ => (1 + x) ^ (α : ℝ)) (binomialSeries ℝ (α : ℝ)) 0 := by
    have := @Real.one_add_rpow_hasFPowerSeriesOnBall_zero;
    exact this.hasFPowerSeriesAt;
  have h_taylor_remainder : ∃ C > 0, ∀ᶠ y in nhds 0, |(1 + y) ^ (α : ℝ) - ∑ i ∈ Finset.range (N + 1), (Ring.choose (α : ℝ) i : ℝ) * y ^ i| ≤ C * |y| ^ (N + 1) := by
    have := h_taylor.isBigO_sub_partialSum_pow ( N + 1 );
    rw [ Asymptotics.isBigO_iff' ] at this;
    simp_all +decide [ _root_.binomialSeries, FormalMultilinearSeries.partialSum ];
    simpa only [ mul_comm ] using this;
  obtain ⟨ C, hC₀, hC ⟩ := h_taylor_remainder;
  refine' ⟨ C, _ ⟩;
  filter_upwards [ hC.filter_mono ( show Filter.Tendsto ( fun n : ℕ => ( n : ℝ ) ⁻¹ ) Filter.atTop ( nhds 0 ) from tendsto_inv_atTop_zero.comp tendsto_natCast_atTop_atTop ), Filter.eventually_gt_atTop 0 ] with n hn hn' ; simp_all +decide [ abs_inv, zpow_neg, mul_comm ];
  convert hn using 1;
  · unfold ratPowSeq; norm_num [ add_div, hn'.ne' ] ;
  · group

:= by
  intro N
  by_cases hN : 0 ≤ N;
  · convert oneAddPow_governs_natOrder α ( Int.toNat N ) using 1; all_goals cases N <;> aesop;
  · 
    have hpval_zero : ∀ n : ℕ, pval (oneAddPow α) N n = 0 := by
      intro n; rw [ pval_eq_finset_sum ] ;
      rw [ Finset.Icc_eq_empty ] <;> norm_num ; linarith [ oneAddPow_order α ];

    have h_ratPowSeq_bounded : ∃ C : ℝ, ∀ᶠ n : ℕ in atTop, |ratPowSeq α n| ≤ C := by
      have h_ratPowSeq_bounded : Filter.Tendsto (fun n : ℕ => ratPowSeq α n) Filter.atTop (nhds 1) := by
        have h_lim : Filter.Tendsto (fun n : ℕ => ((n + 1 : ℝ) / n) ^ (α : ℝ)) Filter.atTop (nhds (1 ^ (α : ℝ))) := by
          norm_num [ add_div ];
          exact le_trans ( Filter.Tendsto.rpow ( Filter.Tendsto.add ( tendsto_const_nhds.congr' ( by filter_upwards [ Filter.eventually_ne_atTop 0 ] with n hn; aesop ) ) ( tendsto_inv_atTop_zero.comp tendsto_natCast_atTop_atTop ) ) tendsto_const_nhds ( Or.inl <| by norm_num ) ) ( by norm_num );
        aesop;
      exact ⟨ _, h_ratPowSeq_bounded.abs.eventually ( ge_mem_nhds <| show |1| < 2 by norm_num ) ⟩;
    exact ⟨ h_ratPowSeq_bounded.choose, by filter_upwards [ h_ratPowSeq_bounded.choose_spec, Filter.eventually_gt_atTop 0 ] with n hn hn'; simpa [ hpval_zero ] using hn.trans ( le_mul_of_one_le_right ( by linarith [ abs_nonneg ( ratPowSeq α n ) ] ) ( one_le_zpow₀ ( by norm_cast ) ( by linarith ) ) ) ⟩

:= by
  obtain ⟨m₀, hm₀⟩ : ∃ m₀ : ℕ, ∀ r : ZHat, Valued.v (F r) ≤ WithZero.exp (m₀ : ℤ) := by
    obtain ⟨m₀, hm₀⟩ : ∃ m₀ : ℕ, ∀ r : ZHat, Valued.v (F r) ≤ WithZero.exp (m₀ : ℤ) := by
      have h_empty : ⋂ m : ℕ, {r : ZHat | Valued.v (F r) > WithZero.exp (m : ℤ)} = ∅ := by
        ext r
        simp [Set.mem_iInter];
        by_cases h : Valued.v ( F r ) = 0;
        · exact ⟨ 0, h.symm ▸ by simp +decide ⟩;
        · cases' h' : Valued.v ( F r ) with m hm;
          · contradiction;
          · cases' m with m hm;
            use Int.toNat m + 1;
            cases m <;> simp_all +decide [ WithZero.exp ];
            exact le_trans ( Int.negSucc_lt_zero _ |> le_of_lt ) ( by norm_num )
      contrapose! h_empty;
      apply_rules [ IsCompact.nonempty_iInter_of_directed_nonempty_isCompact_isClosed ];
      · refine' directed_of_isDirected_le _;
        intro i j hij; intro r hr; exact lt_of_le_of_lt ( WithZero.exp_le_exp.mpr ( mod_cast hij ) ) hr;
      · intro m;
        refine' IsClosed.isCompact _;
        convert isClosed_compl_iff.mpr ( Valued.isOpen_closedBall ℚ⸨X⸩ ( show ( WithZero.exp ( m : ℤ ) ) ≠ 0 from WithZero.exp_ne_zero ) |> IsOpen.preimage F.continuous ) using 1;
        ext; simp [Set.mem_setOf_eq];
      · intro m;
        convert isClosed_compl_iff.mpr ( Valued.isOpen_closedBall ℚ⸨X⸩ ( show ( WithZero.exp ( m : ℤ ) ) ≠ 0 from WithZero.exp_ne_zero ) |> IsOpen.preimage F.continuous ) using 1;
        ext; simp [Set.mem_setOf_eq];
    use m₀;
  use -m₀;
  intro r k hk;
  have := LaurentSeries.valuation_le_iff_coeff_lt_eq_zero ( D := -m₀ ) ( f := F r );
  exact this.mp ( by simpa using hm₀ r ) k hk

:= by
  have h_abs_diff : |pval f M n * pval g M n - pval (f * g) N n| ≤ ∑ i ∈ Finset.Icc (order f) M, ∑ j ∈ Finset.Icc (order g) M, |(f.coeff i : ℝ) * (g.coeff j : ℝ) * (n : ℝ) ^ (-(i + j)) * (if i + j > N then 1 else 0)| := by
    have h_expand : pval f M n * pval g M n - pval (f * g) N n = ∑ i ∈ Finset.Icc (order f) M, ∑ j ∈ Finset.Icc (order g) M, (f.coeff i : ℝ) * (g.coeff j : ℝ) * (n : ℝ) ^ (-(i + j)) * (if i + j > N then 1 else 0) := by
      rw [ pval_eq_finset_sum, pval_eq_finset_sum, pval_eq_finset_sum ];
      have h_prod : ∑ k ∈ Finset.Icc (order (f * g)) N, (f * g).coeff k * (n : ℝ) ^ (-k) = ∑ i ∈ Finset.Icc (order f) M, ∑ j ∈ Finset.Icc (order g) M, (if i + j ≤ N then (f.coeff i : ℝ) * (g.coeff j : ℝ) * (n : ℝ) ^ (-(i + j)) else 0) := by
        have h_cauchy_prod : ∀ k : ℤ, k ≤ N → (f * g).coeff k = ∑ i ∈ Finset.Icc (order f) M, ∑ j ∈ Finset.Icc (order g) M, if i + j = k then (f.coeff i) * (g.coeff j) else 0 := by
          intro k hk;
          rw [ ← Finset.sum_product' ];
          rw [ ← Finset.sum_filter ];
          refine' Finset.sum_subset _ _ <;> intro x hx <;> simp_all +decide [ Finset.mem_addAntidiagonal ];
          · exact ⟨ ⟨ HahnSeries.order_le_of_coeff_ne_zero hx.1, by linarith [ HahnSeries.order_le_of_coeff_ne_zero hx.2.1 ] ⟩, ⟨ HahnSeries.order_le_of_coeff_ne_zero hx.2.1, by linarith [ HahnSeries.order_le_of_coeff_ne_zero hx.1 ] ⟩ ⟩;
          · tauto;
        rw [ Finset.sum_congr rfl fun k hk => by rw [ h_cauchy_prod k ( Finset.mem_Icc.mp hk |>.2 ) ] ];
        simp +decide [ Finset.sum_mul _ _ _, Finset.mul_sum ];
        rw [ Finset.sum_comm, Finset.sum_congr rfl ];
        intro i hi; rw [ Finset.sum_comm ] ; refine' Finset.sum_congr rfl fun j hj => _ ; split_ifs <;> simp_all +decide [ zpow_add₀, zpow_neg ] ;
        · rw [ Finset.sum_eq_single ( i + j ) ] <;> norm_num;
          · exact Or.inl ( by rw [ ← zpow_neg ] ; ring );
          · grind;
          · contrapose!;
            exact fun _ => ⟨ by exact le_trans ( HahnSeries.order_mul ( by aesop ) ( by aesop ) |> le_of_eq ) ( add_le_add ( HahnSeries.order_le_of_coeff_ne_zero ( by aesop ) ) ( HahnSeries.order_le_of_coeff_ne_zero ( by aesop ) ) ), by linarith ⟩;
        · exact Finset.sum_eq_zero fun x hx => by rw [ if_neg ( by linarith [ Finset.mem_Icc.mp hx ] ) ] ; ring;
      rw [ h_prod, Finset.sum_mul ];
      simp +decide [ Finset.mul_sum _ _ _, mul_assoc, mul_comm, mul_left_comm, zpow_add₀ ( by positivity : ( n : ℝ ) ≠ 0 ) ];
      rw [ ← Finset.sum_sub_distrib ] ; congr ; ext i ; rw [ ← Finset.sum_sub_distrib ] ; congr ; ext j ; split_ifs <;> linarith;
    exact h_expand.symm ▸ le_trans ( Finset.abs_sum_le_sum_abs _ _ ) ( Finset.sum_le_sum fun i hi => Finset.abs_sum_le_sum_abs _ _ );
  refine le_trans h_abs_diff ?_;
  rw [ Finset.sum_mul _ _ _ ];
  refine' Finset.sum_le_sum fun i hi => _;
  rw [ Finset.sum_mul _ _ _ ] ; refine' Finset.sum_le_sum fun j hj => _ ; split_ifs <;> simp_all +decide [ abs_mul ];
  exact mul_le_mul_of_nonneg_left ( by exact zpow_le_zpow_right₀ ( mod_cast hn ) ( by linarith ) ) ( by positivity )

:= by

  obtain ⟨B, hB0, hB⟩ := coeff_uniform_bound_range F L M
  obtain ⟨B', hB0', hB'⟩ := coeff_uniform_bound_range G L M
  set C := ((Finset.Icc L M).card * (Finset.Icc L M).card : ℝ) * (B * B') with hC_def;

  have h_bound : ∀ n ≥ 1, |pval (F (ZHat.ofNat n)) M n * pval (G (ZHat.ofNat n)) M n - pval (F (ZHat.ofNat n) * G (ZHat.ofNat n)) N n| ≤ C * (n : ℝ) ^ (-(N + 1)) := by
    intro n hn
    by_cases hfn : F (ZHat.ofNat n) = 0 ∨ G (ZHat.ofNat n) = 0;
    · cases hfn <;> simp +decide [ * ]; all_goals positivity;
    · have h_order : (F (ZHat.ofNat n)).order ≥ L ∧ (G (ZHat.ofNat n)).order ≥ L := by
        constructor <;> contrapose! hfn;
        · exact Or.inl <| by_contra fun h => absurd ( hLF ( ZHat.ofNat n ) _ hfn ) ( by simpa using HahnSeries.coeff_order_ne_zero h );
        · exact Or.inr <| by_contra fun h => by have := hLG ( ZHat.ofNat n ) ( order ( G ( ZHat.ofNat n ) ) ) hfn; exact absurd this ( by simp +decide [ h, coeff_order_eq_zero ] ) ;
      have h_bound : ∀ i ∈ Finset.Icc (order (F (ZHat.ofNat n))) M, ∀ j ∈ Finset.Icc (order (G (ZHat.ofNat n))) M, |((F (ZHat.ofNat n)).coeff i : ℝ)| * |((G (ZHat.ofNat n)).coeff j : ℝ)| ≤ B * B' := by
        exact fun i hi j hj => mul_le_mul ( hB _ _ ( by linarith [ Finset.mem_Icc.mp hi ] ) ( by linarith [ Finset.mem_Icc.mp hi ] ) ) ( hB' _ _ ( by linarith [ Finset.mem_Icc.mp hj ] ) ( by linarith [ Finset.mem_Icc.mp hj ] ) ) ( by positivity ) ( by positivity );
      have h_sum_bound : ∑ i ∈ Finset.Icc (order (F (ZHat.ofNat n))) M, ∑ j ∈ Finset.Icc (order (G (ZHat.ofNat n))) M, (if i + j > N then |((F (ZHat.ofNat n)).coeff i : ℝ)| * |((G (ZHat.ofNat n)).coeff j : ℝ)| else 0) ≤ (Finset.Icc L M).card * (Finset.Icc L M).card * (B * B') := by
        refine' le_trans ( Finset.sum_le_sum fun i hi => Finset.sum_le_sum fun j hj => _ ) _;
        use fun i j => B * B';
        · split_ifs <;> [ exact h_bound i hi j hj; exact mul_nonneg hB0 hB0' ];
        · simp +decide [ mul_assoc, mul_comm, mul_left_comm ];
          gcongr <;> omega;
      convert le_trans ( pval_mul_sub_pointwise ( F ( ZHat.ofNat n ) ) ( G ( ZHat.ofNat n ) ) N M ?_ ?_ n hn ) ( mul_le_mul_of_nonneg_right h_sum_bound <| by positivity ) using 1; all_goals linarith;
  exact ⟨ C, Filter.eventually_atTop.mpr ⟨ 1, fun n hn => h_bound n hn ⟩ ⟩

:= by
  have h_pval_finite : ∀ n : ℕ, |pval (F (ZHat.ofNat n)) M n| ≤ (∑ k ∈ Finset.Icc L M, |((F (ZHat.ofNat n)).coeff k : ℝ)| * (n : ℝ) ^ (-k)) := by
    intro n; rw [ pval_eq_finset_sum ] ; simp +decide ;
    refine' le_trans ( Finset.abs_sum_le_sum_abs _ _ ) _;
    refine' le_trans _ ( Finset.sum_le_sum_of_subset_of_nonneg _ _ );
    rotate_left;
    exact Finset.Icc ( order ( F ( ZHat.ofNat n ) ) ) M |> Finset.filter fun k => k ≥ L;
    · exact fun x hx => Finset.mem_Icc.mpr ⟨ Finset.mem_filter.mp hx |>.2, Finset.mem_Icc.mp ( Finset.mem_filter.mp hx |>.1 ) |>.2 ⟩;
    · exact fun _ _ _ => by positivity;
    · rw [ Finset.sum_filter ];
      gcongr with k hk;
      by_cases hk' : k ≥ L <;> simp [ hk' ];
      rw [ hL ( ZHat.ofNat n ) k (by omega) ]; simp
  obtain ⟨ B, hB₀, hB ⟩ := coeff_uniform_bound_range F L M;
  have h_sum_bound : ∀ n : ℕ, n ≥ 1 → |pval (F (ZHat.ofNat n)) M n| ≤ (∑ k ∈ Finset.Icc L M, B * (n : ℝ) ^ (-L)) := by
    exact fun n hn => le_trans ( h_pval_finite n ) ( Finset.sum_le_sum fun k hk => mul_le_mul ( hB _ _ ( Finset.mem_Icc.mp hk |>.1 ) ( Finset.mem_Icc.mp hk |>.2 ) ) ( by exact zpow_le_zpow_right₀ ( mod_cast hn ) ( by linarith [ Finset.mem_Icc.mp hk |>.1, Finset.mem_Icc.mp hk |>.2 ] ) ) ( by positivity ) ( by positivity ) );
  refine ⟨ ∑ k ∈ Finset.Icc L M, B, ?_ ⟩;
  filter_upwards [ Filter.eventually_ge_atTop 1 ] with n hn using le_trans ( h_sum_bound n hn ) ( by rw [ Finset.sum_mul _ _ _ ] )

:= by
  obtain ⟨ LF, hLF ⟩ := order_uniform_bound F
  obtain ⟨ LG, hLG ⟩ := order_uniform_bound G
  set L := min LF LG with hL_def;
