  have h_eval_leading_coeff : Filter.Tendsto (fun n : ℕ => |(Q.eval ((n : ℕ) : ℚ) : ℚ)| / ((n : ℕ) : ℚ) ^ Q.natDegree) Filter.atTop (nhds (|Q.leadingCoeff|)) := by
    have h_leading_coeff : Filter.Tendsto (fun n : ℕ => (Q.eval (n : ℚ)) / (n : ℚ) ^ Q.natDegree) Filter.atTop (nhds (Q.leadingCoeff)) := by
      have := Polynomial.div_tendsto_atTop_leadingCoeff_div_of_degree_eq Q;
