  · filter_upwards [ Filter.eventually_ge_atTop N, Filter.eventually_gt_atTop 0 ] with n hn hn' ; specialize hN n hn ; rw [ ge_iff_le, le_div_iff₀ ] at hN <;> norm_cast at * ; aesop

:= by
