:= by
  obtain ⟨c, hc_pos, hc⟩ : ∃ c : ℝ, 0 < c ∧ ∀ᶠ n : ℕ in atTop, |pval f f.order n| ≥ c * (n : ℝ) ^ (-f.order) := by
    have h_pval_abs_lower : ∀ᶠ n : ℕ in atTop, |pval f f.order n| = |(f.coeff f.order : ℝ)| * (n : ℝ) ^ (-f.order) := by
      refine' Filter.eventually_atTop.mpr ⟨ 1, fun n hn => _ ⟩ ; rw [ pval_eq_finset_sum ] ; simp +decide [ hn ] ;
    exact ⟨ |f.coeff f.order|, abs_pos.mpr ( by simpa using HahnSeries.coeff_order_ne_zero hf0 ), h_pval_abs_lower.mono fun n hn => hn.ge ⟩;
  obtain ⟨C, hC⟩ : ∃ C : ℝ, ∀ᶠ n : ℕ in atTop, |a n - pval f f.order n| ≤ C * (n : ℝ) ^ (-(f.order + 1)) := by
