      obtain ⟨ N, hN ⟩ := h_div; use N + 1; intros n hn; convert mul_le_mul_of_nonneg_right ( hN n ( by linarith ) ) ( show ( 0 : ℝ ) ≤ ( n : ℝ ) ^ ( -f.order : ℤ ) by positivity ) using 1 ; ring;
